'use strict';
const $=id=>document.getElementById(id);
let baseline,result,selectedTicker,worker,dirty=false;
const colors={navy:'#24475e',orange:'#c77b48',grid:'#eef1f3',muted:'#82919e'};
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const compact=v=>v>=1e9?'$'+(v/1e9).toFixed(2)+'B':v>=1e6?'$'+(v/1e6).toFixed(2)+'M':v>=1000?'$'+(v/1000).toFixed(1)+'K':money(v);
const pct=(v,d=2)=>(100*v).toFixed(d)+'%';
function confidenceText(c){return String(Math.round(c*1000)/10)+'%';}
function parameters(){return {asset_shock:-Number($('shock').value)/100,volatility_multiplier:Number($('vol').value)/100,market:Number($('corr').value)/100,horizon:Number($('horizon').value),confidence:Number($('confidence').value),lgd:Number($('lgd').value)/100,seed:42};}
function updateLabels(){const p=parameters();$('shock-out').textContent=(p.asset_shock===0?'0':'−'+Math.round(-p.asset_shock*100))+'%';$('vol-out').textContent=p.volatility_multiplier.toFixed(2)+'×';$('corr-out').textContent=p.market.toFixed(2);$('lgd-out').textContent=pct(p.lgd,0);}
function markDirty(){updateLabels();dirty=true;$('run-note').textContent='Inputs changed. Run to update all results.';document.querySelectorAll('[data-preset]').forEach(b=>b.classList.remove('selected'));}
function setPreset(name){const x={base:[0,100,25],slowdown:[15,125,40],severe:[30,160,60]}[name];['shock','vol','corr'].forEach((id,i)=>$(id).value=x[i]);markDirty();document.querySelector(`[data-preset="${name}"]`).classList.add('selected');}
function baseLayout(){return {paper_bgcolor:'transparent',plot_bgcolor:'transparent',font:{family:'DM Sans, Arial, sans-serif',size:10,color:colors.muted},margin:{l:55,r:22,t:30,b:50},xaxis:{gridcolor:colors.grid,zeroline:false},yaxis:{gridcolor:colors.grid,zeroline:false},showlegend:false};}
const chartConfig={responsive:true,displayModeBar:false};
function renderCharts(){if(!result||$('view-overview').hidden)return;const r=result,h=r.histogram,edges=h.edges;const x=edges.slice(0,-1).map((v,i)=>(v+edges[i+1])/2);const width=edges.slice(0,-1).map((v,i)=>(edges[i+1]-v)*.84);const probabilities=h.counts.map(v=>v/r.parameters.simulations);
 const l=baseLayout();l.xaxis={...l.xaxis,title:{text:'PORTFOLIO DEFAULT LOSS',standoff:15,font:{size:8}},tickprefix:'$',tickformat:'~s',range:[-r.total_exposure*.012,r.total_exposure*r.parameters.lgd*1.015]};l.yaxis={...l.yaxis,tickformat:'.0%',title:{text:'PROBABILITY',font:{size:8}},rangemode:'tozero'};
 l.shapes=[{type:'rect',xref:'x',yref:'paper',x0:r.risk.var,x1:r.total_exposure*r.parameters.lgd,y0:0,y1:1,fillcolor:'#c77b4810',line:{width:0},layer:'below'},{type:'line',xref:'x',yref:'paper',x0:r.risk.var,x1:r.risk.var,y0:0,y1:1,line:{color:colors.orange,width:1.5,dash:'dot'}}];
 l.annotations=[{x:r.risk.var,y:1.03,xref:'x',yref:'paper',text:'VaR '+compact(r.risk.var),showarrow:false,font:{size:9,color:colors.orange},xanchor:r.risk.var>r.total_exposure*r.parameters.lgd*.85?'right':'left'}];
 Plotly.react('loss-chart',[{type:'bar',x,y:probabilities,width,marker:{color:x.map(v=>v>=r.risk.var?colors.orange:colors.navy)},customdata:edges.slice(0,-1).map((v,i)=>[v,edges[i+1]]),hovertemplate:'Loss bin: $%{customdata[0]:,.0f} – $%{customdata[1]:,.0f}<br>Probability: %{y:.2%}<extra></extra>'}],l,chartConfig);
 const top=[...r.firms].sort((a,b)=>b.expected_loss-a.expected_loss).slice(0,6).reverse();const l2=baseLayout();l2.margin={l:58,r:65,t:20,b:35};l2.xaxis={...l2.xaxis,tickprefix:'$',tickformat:'~s'};l2.yaxis={...l2.yaxis,showgrid:false};
 Plotly.react('contribution-chart',[{type:'bar',orientation:'h',x:top.map(f=>f.expected_loss),y:top.map(f=>f.ticker),text:top.map(f=>compact(f.expected_loss)),textposition:'outside',cliponaxis:false,marker:{color:top.map((f,i)=>i===5?colors.orange:'#637f91')},hovertemplate:'%{y}<br>Expected loss: $%{x:,.0f}<extra></extra>'}],l2,chartConfig);
}
function renderCorrelation(){if(!result||$('view-issuers').hidden)return;const l=baseLayout();l.margin={l:55,r:30,t:15,b:60};l.xaxis={tickangle:-55,tickfont:{size:8},showgrid:false};l.yaxis={autorange:'reversed',tickfont:{size:8},showgrid:false};Plotly.react('correlation-chart',[{type:'heatmap',z:result.panel.correlation,x:result.firms.map(f=>f.ticker),y:result.firms.map(f=>f.ticker),zmin:0,zmax:1,colorscale:[[0,'#f1f4f7'],[.5,'#809bac'],[1,'#183a50']],colorbar:{thickness:9,len:.8,tickfont:{size:9}},hovertemplate:'%{x} / %{y}<br>Correlation: %{z:.2f}<extra></extra>'}],l,chartConfig);}
function renderMetrics(){const r=result,k=r.risk,p=r.parameters;$('el').textContent=compact(k.expected_loss);$('var').textContent=compact(k.var);$('es').textContent=compact(k.expected_shortfall);$('zero').textContent=pct(k.zero_loss_probability,1);$('el-sub').textContent=pct(k.expected_loss/r.total_exposure)+' of exposure · analytic';$('var-sub').textContent=pct(k.var/r.total_exposure)+' of total exposure';$('es-sub').textContent='Average in worst '+(100-p.confidence*100).toFixed(1).replace('.0','')+'% of paths';document.querySelectorAll('.confidence-label').forEach(e=>e.textContent=confidenceText(p.confidence));$('tail-ratio').textContent=(k.expected_shortfall/k.expected_loss).toFixed(1)+'×';$('insight').textContent='At '+confidenceText(p.confidence)+' confidence, losses in the worst scenarios average '+compact(k.expected_shortfall)+', compared with an expected loss of '+compact(k.expected_loss)+'.';$('simulation-note').textContent='Seed '+p.seed+' · '+p.horizon+'-year horizon · '+(p.asset_shock===0?'Base assets':pct(p.asset_shock,0)+' asset shock');$('engine-status').textContent=r.engine.startsWith('Python')?'Python baseline · 100,000 paths':'Browser simulation · 100,000 paths';}
function renderTable(){if(!result)return;const q=$('search').value.toLowerCase(),sort=$('sort').value;let firms=result.firms.filter(f=>(f.name+' '+f.ticker+' '+f.sector).toLowerCase().includes(q));firms.sort(sort==='name'?(a,b)=>a.name.localeCompare(b.name):sort==='leverage'?(a,b)=>b.debt/b.stressed_asset_value-a.debt/a.stressed_asset_value:(a,b)=>b.probability_of_default-a.probability_of_default);const body=$('firm-table');body.replaceChildren();for(const f of firms){const tr=document.createElement('tr');if(f.ticker===selectedTicker)tr.classList.add('selected');const cell=document.createElement('td'),btn=document.createElement('button');btn.className='issuer-button';btn.textContent=f.ticker;btn.onclick=()=>selectFirm(f.ticker);cell.append(btn);const small=document.createElement('small');small.textContent=f.name;cell.append(small);tr.append(cell);for(const text of [f.sector,compact(f.stressed_asset_value),pct(f.stressed_asset_volatility,1),f.distance_to_default.toFixed(2)+' σ']){const td=document.createElement('td');td.textContent=text;tr.append(td);}const td=document.createElement('td'),chip=document.createElement('span');chip.className='pd-chip '+(f.probability_of_default>.15?'high':f.probability_of_default>.05?'elevated':'');chip.textContent=pct(f.probability_of_default);td.append(chip);tr.append(td);body.append(tr);}if(!firms.length){let tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=6;td.textContent='No issuers match your search.';tr.append(td);body.append(tr);}$('table-count').textContent=firms.length+' of '+result.firms.length+' issuers · Synthetic inputs · Select a ticker for details';}
function selectFirm(ticker){selectedTicker=ticker;const f=result.firms.find(x=>x.ticker===ticker);if(!f)return;$('detail-name').textContent=f.name+' / '+f.ticker;const content=$('detail-content');content.replaceChildren();const entries=[['Input equity value',compact(f.equity)],['Input equity volatility',pct(f.equity_volatility,1)],['Debt boundary',compact(f.debt)],['Exposure',money(f.exposure)],['Calibrated assets',compact(f.asset_value)],['Calibrated asset volatility',pct(f.asset_volatility,1)],['Solver relative residual',f.relative_residual.toExponential(2)],['Solver evaluations',String(f.evaluations)]];for(const [label,value] of entries){const d=document.createElement('div'),s=document.createElement('small'),b=document.createElement('strong');s.textContent=label;b.textContent=value;d.append(s,b);content.append(d);}let note=document.createElement('p');note.className='detail-note';note.textContent='Current scenario: '+compact(f.stressed_asset_value)+' assets, '+pct(f.stressed_asset_volatility,1)+' asset volatility. Model PD '+pct(f.probability_of_default)+' versus simulated '+pct(f.simulated_default_rate)+'. Calibration residuals describe numerical fit, not predictive accuracy.';content.append(note);renderTable();}
function apply(r){result=r;dirty=false;renderMetrics();renderTable();selectFirm(selectedTicker||r.firms[0].ticker);renderCharts();renderCorrelation();$('export-json').disabled=false;$('export-csv').disabled=false;}
function showTab(name){document.querySelectorAll('[data-tab]').forEach(b=>{let active=b.dataset.tab===name;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});document.querySelectorAll('.view').forEach(v=>{let active=v.id==='view-'+name;v.hidden=!active;v.classList.toggle('active',active);});if(name==='overview')renderCharts();if(name==='issuers')renderCorrelation();}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCsv(){const keys=['ticker','name','sector','equity','debt','asset_value','asset_volatility','stressed_asset_value','stressed_asset_volatility','probability_of_default','simulated_default_rate','distance_to_default','expected_loss','relative_residual'];const quote=v=>'"'+String(v).replaceAll('"','""')+'"';download('credit-atlas-issuers.csv',keys.join(',')+'\n'+result.firms.map(f=>keys.map(k=>quote(f[k])).join(',')).join('\n'),'text/csv');}
function setBusy(busy){document.querySelectorAll('#shock,#vol,#corr,#horizon,#confidence,#lgd,[data-preset]').forEach(e=>e.disabled=busy);$('run').disabled=busy||!baseline;}
function run(){if(!baseline)return;if(worker)worker.terminate();$('global-error').hidden=true;setBusy(true);document.querySelector('.progress-track').hidden=false;$('progress').style.width='0%';$('run-note').textContent='Simulating 100,000 correlated scenarios…';const p=parameters();worker=new Worker('worker.js');worker.onmessage=({data})=>{if(data.progress!==undefined)$('progress').style.width=data.progress*100+'%';if(data.error)fail(data.error);if(data.result){apply(data.result);setBusy(false);document.querySelector('.progress-track').hidden=true;$('run-note').textContent='Complete in '+(data.result.elapsed_ms/1000).toFixed(2)+'s · 100,000 paths · Seed 42';worker.terminate();worker=null;}};worker.onerror=()=>fail('Simulation could not run. Try resetting the demo or use the downloadable Python version.');worker.postMessage({base:baseline,parameters:p});}
function fail(message){$('global-error').textContent=message;$('global-error').hidden=false;setBusy(false);document.querySelector('.progress-track').hidden=true;$('run-note').textContent='Run failed; previously displayed results are unchanged.';if(worker){worker.terminate();worker=null;}}
for(const id of ['shock','vol','corr','horizon','confidence','lgd'])$(id).addEventListener('input',markDirty);
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>setPreset(b.dataset.preset));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));document.querySelectorAll('[data-go]').forEach(a=>a.onclick=e=>{e.preventDefault();showTab(a.dataset.go);document.querySelector('.tabbar').scrollIntoView({behavior:'smooth',block:'start'});});$('reset').onclick=()=>{if(worker){worker.terminate();worker=null;}setBusy(false);setPreset('base');$('horizon').value='1';$('confidence').value='.99';$('lgd').value='60';updateLabels();if(baseline){apply(baseline);$('run').disabled=false;$('run-note').textContent='Restored the reproducible Python baseline.';}document.querySelector('.progress-track').hidden=true;$('global-error').hidden=true;};$('run').onclick=run;$('export-json').onclick=()=>download('credit-atlas-results.json',JSON.stringify(result,null,2),'application/json');$('export-csv').onclick=exportCsv;$('search').oninput=renderTable;$('sort').onchange=renderTable;
fetch('baseline.json').then(r=>{if(!r.ok)throw Error('Could not load the baseline data.');return r.json();}).then(r=>{baseline=r;apply(r);$('run').disabled=false;$('run-note').textContent='Python baseline loaded · Run to explore your own scenario.';$('verification').textContent='Python baseline: 20 converged calibrations · Max relative residual '+Math.max(...r.firms.map(f=>f.relative_residual)).toExponential(2)+' · 100,000 seeded paths. See tests/ for numerical and ingestion checks.';}).catch(e=>fail(e.message));
